spec.expr:
100 *
sum by (mode) (
  rate(
    node_cpu_seconds_total{
      mode=~"user|system|iowait|idle"
    }[5m]
  )
) 
/ ignoring(mode) group_left 
sum (
    rate(
        node_cpu_seconds_total{
            mode=~"user|system|iowait|idle"
        }[5m]
    )
)

topk(
  10,
  sum by (groupname) (
    namedprocess_namegroup_memory_bytes{
      job="process",
      memtype="proportionalResident"
    }
  )
)

100 * (
  1 -
  node_filesystem_avail_bytes{
    mountpoint="/",
    fstype!="tmpfs"
  }
  /
  node_filesystem_size_bytes{
    mountpoint="/",
    fstype!="tmpfs"
  }
)

100 * (
  1 -
  node_filesystem_avail_bytes{
    mountpoint="/home",
    fstype!="tmpfs"
  }
  /
  node_filesystem_size_bytes{
    mountpoint="/home",
    fstype!="tmpfs"
  }
)
